AUTHORED.update({
8:dict(title='Pagbasa sa mga pagbabawal, babala, at palatandaan ng kemikal',objective='Ihiwalay ang ibig sabihin ng pagbabawal at babala.\nHuwag gamitin ang lalagyang hindi malinaw ang label; magpatunay muna.',paragraphs=[
('Pag-unawa at pagpapasya','May palatandaang pangkaligtasan na nagbabawal ng kilos, nagbababala sa pag-iral ng panganib, o tumutukoy sa lugar at kagamitang kailangan kapag may emerhensiya. Huwag hugis lamang ang kabisaduhin; isipin kung anong kilos ang kailangan sa mismong lugar.\nAng “bawal pumasok” ay hindi nangangahulugang maaari basta mag-ingat. Ang babala sa pagkakuryente ay nagsasabing may panganib mula sa elektrisidad. Bukod sa pagsunod sa palatandaan, tiyakin ang pamamaraan ng kagamitan at awtoridad sa pagpasok.\nPara sa kemikal, suriin ang label ng lalagyan at safety data sheet. Magkakaiba ang panganib ayon sa sangkap, gaya ng madaling pagliyab, pagkaagnas, o epekto sa kalusugan. Huwag hulaan ang laman sa kulay o amoy lamang at huwag gumamit ng likido mula sa lalagyang walang label.\nBago pa magkaroon ng emerhensiya, tiyakin ang lokasyon at daan patungo sa fire extinguisher, AED, at lugar ng paglikas. Huwag sa oras ng emerhensiya pa lamang hanapin ang mga ito. Kung may bagay na nakaharang sa daanan ng paglikas, hilinging ayusin ito ayon sa tuntunin ng lugar ng trabaho.'),
('Halimbawa sa lugar ng trabaho','Habang naghahanda ng paglilinis, may lalagyang hindi mabasa ang label at may nakasanayang likidong panlinis sa tabi nito.\n1. Huwag gamitin ang lalagyang hindi mabasa ang label; huwag ihalo o ilipat sa ibang lalagyan ang laman.\n2. Sabihin sa taong namamahala ang lokasyon at kondisyon ng lalagyan. Tiyakin ang laman at wastong paghawak dito.\n3. Para sa bagay na pinayagang gamitin, suriin ang label, safety data sheet, at pamamaraan ng trabaho.\nAng katabing lalagyang magkahawig ay hindi patunay na pareho ang laman.')],terms=['Hindi pinapayagang gawin ang kilos na iyon.','Palatandaang nagpapabatid na may panganib o kondisyong nakasasama.','Pagkasira ng bagay dahil sa kemikal na epekto o katulad nito.','Daanang ginagamit upang lumayo sa panganib.'],activity='7 minuto: Sa kathang-isip na plano ng lugar ng trabaho, ilagay ang bawal pumasok, babala sa pagkakuryente, fire extinguisher, at daanan ng paglikas. Isulat ang kailangang kilos para sa bawat isa.',safety=['Huwag subukang tukuyin ang hindi kilalang likido sa paghawak o pag-amoy dito.'],summary='Iugnay sa tiyak na kilos ang kahulugan ng palatandaan.\nIpasuri bago gamitin ang label na hindi mabasa.'),
9:dict(title='Pagtingin sa kalidad mula sa pangangailangan ng gumagamit',objective='Ihiwalay ang kalidad sa disenyo, paggawa, at distribusyon; ipaliwanag ang batayan ng pagtanggap o pagtanggi.',paragraphs=[
('Prinsipyo at batayan ng pagpapasya','Hindi sa kaginhawahan lamang ng gumagawa nakabatay ang kalidad. Nagsisimula ito sa pagtugon sa pangangailangan ng gumagamit. Ang kalidad sa disenyo ay kaugnay ng nilalayong kakayahan at espesipikasyon. Ang kalidad sa paggawa ay ang aktuwal na pagkakamit nito sa produkto. Ang kalidad sa distribusyon ay kaugnay ng paghahatid ng tamang bagay sa tamang dami, oras, at kondisyon. Kahit tama ang dimensiyon, hindi natutugunan ang buong pangangailangan kung kulang ang dumating na dami.'),
('Pagsasaayos ng halimbawa sa trabaho','May order na kailangang maghatid ng 80 bracket na pareho ang espesipikasyon bago ang takdang araw. Pasok sa pamantayan ang dimensiyon ng 80 ginawang piyesa, ngunit natuklasang 78 lamang ang nasa pakete. Hindi maaaring gamitin ang resulta ng pagsusuri sa dimensiyon bilang patunay na pasado rin ang dami. Suriin ang dami sa pakete, label, at rekord ng pagpapadala, at ikonsulta sa taong namamahala ang pagtugon sa kakulangan.'),
('Rekord at karaniwang pagkakamali','Ang QCD ay kalidad, gastos, at oras ng paghahatid; maaari itong tawaging QCDS kapag isinama ang kaligtasan. Hindi maaaring laktawan ang inspeksiyon upang umabot sa takdang oras o magpalit ng materyal nang walang pahintulot upang bumaba ang gastos. Iugnay ang pangangailangan, pamantayan ng paghatol, at aktuwal na resulta. Kung kailangang magbago, kumpirmahin sa may awtoridad.')],terms=['Kalidad na itinakdang layunin sa yugto ng disenyo.','Kakayahan o kondisyong nakamit sa paggawa.','Kalidad kaugnay ng bagay, dami, oras, at kondisyon hanggang makarating sa kostumer.','Nilalamang kailangang matugunan.'],fullActivity=mid_activity('7 minuto: Gumawa ng kathang-isip na order. Para sa apat na paksa—kakayahan at dimensiyon, dami, oras ng paghahatid, at kondisyon ng pakete—isulat ang pangangailangan at paraan ng pagtiyak.'),safety=['Huwag laktawan ang pamamaraan ng kaligtasan o kinakailangang inspeksiyon dahil sa oras o gastos.'],summary='Isaalang-alang ang kalidad ayon sa pangangailangan. Ang pasado sa dimensiyon ay hindi awtomatikong pasado sa dami o kondisyon ng pagpapadala.'),
10:dict(title='Pagsisiyasat sa problema sa kalidad mula sa pagbabago ng 4M',objective='Ayusin ang pagbabago sa tao, kagamitan, materyal, at pamamaraan; ihiwalay ang katotohanan sa hinalang sanhi.',paragraphs=[
('Prinsipyo at batayan ng pagpapasya','Ang 4M sa paggawa ay tao, makina o kagamitan, materyal o piyesa, at pamamaraan. Kapag nagbago ang kalidad, gamitin ang apat na pananaw upang hanapin ang pagbabago sa kondisyon at mabawasan ang hindi nasusuri. Hindi ito pag-uuri upang sabihing ang bagong nakatalaga agad ang sanhi. Siyasatin din kung may kasabay na pagpapalit ng kasangkapan o lot ng materyal.'),
('Pagsasaayos ng halimbawa sa trabaho','Pasok sa pamantayan ang diyametro ng butas sa umaga, ngunit lumampas sa unang pagsukat sa hapon. Makikita sa rekord na pinalitan ang kasangkapan at nagpalit din ng nakatalaga noong tanghali. Unang linawin ang huling oras na natiyak na pasado at unang oras na nakumpirmang hindi ayon sa espesipikasyon. Suriin ang pagkakabit ng kasangkapan, ginamit na materyal, setting, at rekord ng pamamaraan. Huwag tiyaking isa lamang sa dalawang pagbabago ang sanhi. Itakda kasama ng taong namamahala ang pagkakasunod-sunod ng pagsuri.'),
('Rekord at karaniwang pagkakamali','Sa prinsipyong tatlong aktuwal, tiyakin ang katotohanan sa aktuwal na lugar, aktuwal na bagay, at aktuwal na kalagayan. Obserbahan sa saklaw na ligtas suriin at itugma sa rekord. Kahit nakapili na ng hakbang, kailangan pa rin ang PDCA upang ihambing ang resulta sa layunin at magpatuloy sa pagpapabuti. Ang isang piyesang pumasa matapos ang pagbabago ay hindi patunay na matatag na ang buong proseso.')],terms=['Pananaw sa kondisyon ng paggawa ayon sa tao, makina, materyal, at pamamaraan.','Aktuwal na produkto o bagay na sinusuri.','Posibleng paliwanag o sanhi bago ito mapatunayan.','Isang yugto ng gawaing bumubuo sa paggawa.'],fullActivity=mid_activity('7 minuto: Gumawa ng kathang-isip na pagkakasunod-sunod ng hindi normal na dimensiyon. Para sa bawat 4M, gumawa ng dalawang kolum: natiyak na katotohanan at kailangan pang siyasatin.'),safety=['Huwag ipasok ang kamay sa umaandar na makina o alisin ang aparatong pangkaligtasan para lamang magsiyasat ng sanhi.'],summary='Pananaw sa pagsisiyasat ang 4M, hindi patunay ng sanhi. Tiyakin ang katotohanan at patuloy na suriin ang bisa ng hakbang.'),
11:dict(title='Pagkilala sa pagkakaiba ng pamantayan sa trabaho at QC process chart',objective='Ihiwalay ang tagubilin sa paraan ng trabaho sa mga item, dalas, at tugon sa hindi normal na ginagamit upang kontrolin ang kalidad.',paragraphs=[
('Prinsipyo at batayan ng pagpapasya','Nililinaw ng pamantayan sa trabaho ang gawain, ayos, kagamitan, kasangkapan, at mahahalagang kondisyon upang mapanatili ang kinakailangang kalidad kahit magpalit ang tao o oras. Sa QC process chart, inaayos para sa bawat proseso kung ano ang kokontrolin, sa anong paraan at dalas, at paano tutugon kapag may hindi normal. Kahit pareho ang proseso, magkaiba ang papel ng paraan ng paggawa at sistema ng pagkontrol.'),
('Pagsasaayos ng halimbawa sa trabaho','Sa kathang-isip na prosesong pagputol, nasa pamantayan ang paraan ng pagkakapit ng materyal at kasangkapang gagamitin. Sa QC process chart, dapat sukatin ang haba sa simula at bawat 30 minuto gamit ang itinakdang instrumento. Kung labas sa saklaw, ihiwalay ang mga apektadong produkto at kontakin ang taong namamahala. Ang pagsunod sa pagkakasunod-sunod ng trabaho ay hindi dahilan upang laktawan ang pagsukat bawat 30 minuto. Gayundin, ang pagsukat lamang ay hindi dahilan upang laktawan ang tamang pagkakapit.'),
('Rekord at karaniwang pagkakamali','Sa pagbasa ng dokumento, sabay na tiyakin ang produktong saklaw, proseso, numero ng dokumento, at rebisyon. Kung magkaiba ang kondisyon sa luma at bagong bersiyon, magtanong; huwag pumili batay sa karanasan lamang. Alamin ang paghawak sa hindi normal na produkto, saan itatala, at sino ang kokontakin bago magsimula. Kathang-isip lamang ang dalas dito; sa aktuwal na trabaho, gamitin ang itinakda para sa sariling proseso.')],terms=['Dokumentong nagtatakda ng nilalaman, ayos, at paraan ng trabaho.','Buod ng mga item, paraan, dalas ng kontrol, at tugon sa hindi normal sa bawat proseso.','Agwat ng oras o bilang ng pagsusuring ginagawa para sa kontrol.','Pagsusuri at pagbabago sa nilalaman ng dokumento.'],fullActivity=mid_activity('7 minuto: Para sa kathang-isip na pagbubutas, gumawa ng talaang naghihiwalay sa tatlong nilalaman ng pamantayan sa trabaho at limang nilalaman ng QC process chart.'),safety=['Huwag palitan nang walang pahintulot ang aprubadong tagubilin sa trabaho ng dalas ng pagsusuring nasa materyal na ito.'],summary='Ipinapakita ng pamantayan ang paraan ng paggawa; ng QC process chart naman ang sistema ng kontrol. Tiyakin ang saklaw at rebisyon at sundin ang pareho.'),
12:dict(title='Pagpili ng QC tool ayon sa layunin',objective='Ihiwalay ang gamit ng check sheet, Pareto chart, histogram, at iba pang kasangkapan.',paragraphs=[
('Prinsipyo at batayan ng pagpapasya','Gumamit ng check sheet sa pagtipon ng datos, Pareto chart upang makita ang prayoridad ayon sa bilang ng bawat kategorya, at histogram upang makita ang distribusyon ng dimensiyon at katulad nito. Nakatutulong ang line graph sa pagbabago sa oras, control chart sa pagmamasid sa katatagan ng proseso, at scatter plot sa relasyon ng dalawang dami. Sa cause-and-effect diagram, ayusin ang mga posibleng sanhi. Bago gumawa ng diagram, itakda kung ano ang gustong pasyahan.'),
('Pagsasaayos ng halimbawa sa trabaho','Sa isang linggo, naitala ang 18 dent, 9 dumi, at 3 pagbabago ng kulay bilang depektong panlabas. Ang kabuuan ay 30. Sa Pareto chart, 60% ang pinagsama-samang porsiyento hanggang dent, 90% hanggang dumi, at 100% hanggang pagbabago ng kulay. Nakatutulong ito upang simulan ang pagsisiyasat sa dent na pinakamarami, ngunit huwag ipagpaliban ang depektong mataas ang panganib o tindi dahil lamang kakaunti ang bilang.'),
('Rekord at karaniwang pagkakamali','Dahil distribusyon ang ipinapakita ng histogram, hindi makikita rito ang orihinal na pagkakasunod-sunod sa oras. Kahit may nakikitang relasyon sa scatter plot, hindi nito lamang mapapatunayan ang sanhi at bunga. Magkaiba rin ang control limits ng control chart at specification limits para sa pagtanggap ng produkto. Gamitin ang diagram at pamantayang naaayon sa layunin; huwag magpasya batay sa hitsura lamang.')],terms=['Diagram ng bilang ng bawat kategorya at pinagsama-samang porsiyento upang matukoy ang dapat pagtuunan.','Diagram ng distribusyon gamit ang dalas sa mga takdang pagitan.','Diagram na nagpapakita ng pares ng dalawang dami bilang mga tuldok.','Hangganang itinakda sa control chart upang bantayan ang pagbabago ng proseso.'],fullActivity=mid_activity('7 minuto: Gumawa ng kathang-isip na bilang ng depekto sa apat na kategorya at kalkulahin ang kabuuan at pinagsama-samang porsiyento. Isulat din ang diagram na pipiliin para sa pagkalat ng dimensiyon at pagbabago sa oras.'),safety=['Huwag maliitin ang seryosong depektong pangkaligtasan batay lamang sa bilang.'],summary='Piliin ang diagram ayon sa gustong siyasatin. Huwag ipaghalo ang kahulugan ng pinagsama-samang porsiyento, sanhi at bunga, at control limits.'),
13:dict(title='Pagtatala matapos tiyakin ang SI units at mga prefix',objective='Ihiwalay ang mga base unit sa conversion ng yunit at itala ang numero kasama ang yunit.',paragraphs=[
('Prinsipyo at batayan ng pagpapasya','Ang pitong SI base unit ay m para sa haba, kg para sa masa, s para sa oras, A para sa electric current, K para sa thermodynamic temperature, mol para sa dami ng sangkap, at cd para sa luminous intensity. Ginagamit din sa trabaho ang mm, g, ms, at iba pa. Kahit pareho ang numero, magkaiba ang dami kung magkaiba ang yunit. Sabay na tiyakin ang yunit sa tagubilin, display, at kolum ng rekord.'),
('Pagsasaayos ng halimbawa sa trabaho','Kung itatala sa metro ang kapal na 0.8 mm, ito ay 0.0008 m dahil 1 mm=0.001 m. Ang masang 2.4 kg ay 2400 g; ang oras na 750 ms ay 0.75 s. Mas madaling makita ang pagkakamaling 1000 beses kung ibabalik sa orihinal na yunit matapos ang conversion at titingnan kung pareho pa rin ang dami.'),
('Rekord at karaniwang pagkakamali','Ihiwalay din ang malaking titik at maliit na titik. Yunit ng haba ang m, ngunit ang unang m sa mm ay prefix na nagsasaad ng isang bahagi sa isang libo. Magkaibang dami ang masa sa kg at puwersa sa N. Huwag magpasya mula sa salitang “bigat” lamang; tingnan kung masa o puwersa ang hinihingi ng dokumento. Panatilihin ang yunit kahit sa gitna ng pagkukuwenta upang masuri ito.')],terms=['Sistemang nagpapahayag ng mga dami sa magkakatulad na yunit.','Dami ng materyal sa isang bagay; kg ang SI base unit nito.','Idinadagdag bago ang yunit upang ipakita ang multiplier o bahagi.','Pagpapahayag muli ng parehong dami sa ibang yunit.'],fullActivity=mid_activity('7 minuto: I-convert ang 0.35 mm, 1800 g, at 250 ms sa m, kg, at s, at ibalik upang masuri. Gumawa rin ng talaan ng pitong base unit at kaukulang dami.'),safety=['Kung iko-convert at ilalagay sa kagamitan ang setting, tiyakin ang yunit sa display at aprubadong halaga.'],summary='Basahin ang numero kasama ang yunit. Suriin ang conversion sa pagbabalik sa orihinal na dami at huwag ipaghalo ang masa at puwersa.'),
14:dict(title='Paghiwalay sa saklaw ng inspeksiyon at porsiyento ng hindi ayon sa espesipikasyon',objective='Ihiwalay ang layunin ng pagtanggap, in-process, at bago-magpadalang inspeksiyon; kalkulahin ang porsiyentong hindi ayon sa espesipikasyon na malinaw ang denominator.',paragraphs=[
('Prinsipyo at batayan ng pagpapasya','Tinitingnan ng incoming inspection kung tugma sa espesipikasyon ang biniling bagay; ng in-process inspection kung tugma ang katangian habang ginagawa; at ng shipping inspection kung natutugunan ng tapos na produkto ang pangangailangan. Lahat ng saklaw ang sinusuri sa inspeksiyon ng lahat ng saklaw, samantalang takdang sample ang sinusuri sa sampling inspection. Huwag baguhin ang bilang, paraan ng pagpili, o pamantayan ng sample ayon lamang sa kaginhawahan sa sandaling iyon.'),
('Pagsasaayos ng halimbawa sa trabaho','Mula sa kathang-isip na lot na 600 piyesa, sinuri ang 60 ayon sa pamamaraan at may 3 na hindi ayon sa espesipikasyon. Ang porsiyento sa sample ay 3÷60×100=5%. Kung 3÷600×100=0.5% ang gagamitin, mali nitong ituturing na pasado ang 540 na hindi sinuri. Huwag ding ipasya ang pagtanggap sa lot mula sa 5% lamang; sundin ang itinakdang acceptance number at iba pang kondisyon.'),
('Rekord at karaniwang pagkakamali','Kahit may dalawang gasgas sa isang produkto, isa lamang iyon sa bilang ng produktong hindi ayon sa espesipikasyon. Huwag ihalo ang bilang ng gasgas at bilang ng hindi ayon sa espesipikasyong produkto. Itala kung lahat o sample lamang ang sinuri, saklaw na panahon, at lot number. Impormasyon tungkol sa kondisyon ng lot ang sampling result, hindi garantiya na lahat ng hindi sinuri ay ayon sa espesipikasyon.')],terms=['Inspeksiyon kung natutugunan ng biniling at inihatid na bagay ang hinihinging espesipikasyon.','Inspeksiyong pumipili ng bahagi ng saklaw ayon sa takdang paraan.','Bahagi ng bilang ng produktong hindi ayon sa espesipikasyon kumpara sa kabuuang saklaw.','Pangkat ng produktong pinamamahalaan nang magkakasama ayon sa parehong kondisyon at kaugnay na batayan.'],fullActivity=mid_activity('7 minuto: Hiwalay na kalkulahin ang porsiyento para sa 6 sa 240 na sinuring lahat at 2 sa 40 na sample. Ilagay ang denominator, saklaw, at kung may hindi sinuri, at isulat ang dagdag na kondisyong kailangan para sa pagtanggap sa lot.'),safety=['Huwag ihalo o ipasa bilang ayon sa espesipikasyon ang hindi ayon dito o hindi pa nahatulang produkto nang walang pahintulot.'],summary='Ipahayag ang denominator at saklaw ng porsiyento. Huwag tiyakin ang kondisyon ng hindi sinuri o pagtanggap sa lot mula sa porsiyento ng sample lamang.')
})
